    # Cada liga queda con los tipos que ya usa (categorías, partidos, tarifas y arbitraje por equipo),
    # para que ningún tipo en uso desaparezca de las listas
    con = op.get_bind()
    usados = con.execute(sa.text("""
        SELECT liga_id, modalidad FROM categorias WHERE modalidad IS NOT NULL
        UNION SELECT j.liga_id, p.modalidad FROM partidos p JOIN jornadas j ON j.id = p.jornada_id
              WHERE p.modalidad IS NOT NULL
        UNION SELECT liga_id, modalidad FROM tarifas
        UNION SELECT liga_id, modalidad FROM cuotas_equipo
    """)).fetchall()
    principales = dict(con.execute(sa.text("SELECT id, modalidad FROM ligas")).fetchall())
    orden = ["futbol_11", "futbol_7", "bardas"]
    otras: dict[int, set[str]] = {}
    for liga_id, modalidad in usados:
        if liga_id in principales and modalidad in orden and modalidad != principales[liga_id]:
            otras.setdefault(liga_id, set()).add(modalidad)
    for liga_id, tipos in otras.items():
        con.execute(sa.text("UPDATE ligas SET otras_modalidades = :csv WHERE id = :id"),
                    {"csv": ",".join(m for m in orden if m in tipos), "id": liga_id})


